import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {[number,number,number]} position
 * @property {[number,number,number]} rotation
 * @property {[number,number,number]} scale
 * @property {{imageUrl:string}} assets
 * @property {string} textContent
 * @property {Object} atlas
 * @property {{x:number,y:number,w:number,h:number}} atlas.sourceRect
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {(url:string)=>Promise<any>} glbLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {{texture:THREE.Texture, createTextPlane:(text:string,opts:any)=>THREE.Object3D}} fontAtlas
 * @property {(event:string)=>void} emit
 */

/**
 * Create a journal card label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ---------- Group ----------
  const group = new THREE.Group();
  group.position.set(...config.position);
  group.rotation.set(...config.rotation);
  group.scale.set(...config.scale);
  group.name = 'journal-card-label';

  // ---------- Textured Plane ----------
  const planeGeo = new THREE.PlaneGeometry(1, 1);
  const cardTex = ctx.textureLoader(config.assets.imageUrl);
  const cardMat = new MeshBasicNodeMaterial({ map: cardTex, transparent: true });
  const cardMesh = new THREE.Mesh(planeGeo, cardMat);
  cardMesh.name = 'card-plane';
  group.add(cardMesh);

  // ---------- Text (MSDF) ----------
  const atlasTex = ctx.fontAtlas.texture;
  // ensure repeat wrapping for UV cropping
  atlasTex.wrapS = THREE.RepeatWrapping;
  atlasTex.wrapT = THREE.RepeatWrapping;

  const { x, y, w, h } = config.atlas?.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
  const texW = atlasTex.image?.width || 1024;
  const texH = atlasTex.image?.height || 1024;

  const offsetX = x / texW;
  const offsetY = y / texH;
  const repeatX = w / texW;
  const repeatY = h / texH;

  const textMat = new MeshBasicNodeMaterial({
    map: atlasTex,
    transparent: true,
    // tint the text with the ink color
    color: new THREE.Color('#16161d')
  });
  textMat.map.offset.set(offsetX, offsetY);
  textMat.map.repeat.set(repeatX, repeatY);

  const textGeo = new THREE.PlaneGeometry(0.8, 0.2);
  const textMesh = new THREE.Mesh(textGeo, textMat);
  textMesh.position.set(0, 0, 0.01); // slightly in front of the card
  textMesh.name = 'card-label-text';
  group.add(textMesh);

  // ---------- Interaction Handlers ----------
  const baseY = group.position.y;
  const liftAmount = 0.15; // scene units

  const handlers = {
    /** @param {PointerEvent} evt */
    hover: () => {
      gsap.to(group.position, {
        y: baseY + liftAmount,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    /** @param {PointerEvent} evt */
    hoverOut: () => {
      gsap.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    /** @param {MouseEvent} evt */
    click: () => {
      ctx.emit('hub-journal.select');
    }
  };
  group.userData.handlers = handlers;

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    // stop any GSAP tweens targeting this group
    gsap.killTweensOf(group.position);

    // dispose geometries & materials (textures are shared, do not dispose)
    planeGeo.dispose();
    cardMat.dispose();
    textGeo.dispose();
    textMat.dispose();
  };

  return group;
}
